import { supabase, createSessionClient } from '../../config/supabase.js';
import { sendError, mapDbError } from '../../utils/respond.js';

// ─── Password policy (CC-4 Part C) ───────────────────────────────────────────
// Deliberately small. The real defence against guessing is the auth_attempts
// lockout from migration 005, not a long blocklist — this only stops the
// handful of passwords an attacker tries first, on every account, for free.
//
// Nothing in this file ever logs, stores or returns a password. The only value
// that leaves the process is the boolean `has_password` on the users row.
const MIN_PASSWORD_LENGTH = 8;

const COMMON_PASSWORDS = new Set([
    'password', 'password1', 'password123', '12345678', '123456789',
    '1234567890', 'qwerty123', 'qwertyuiop', 'iloveyou', 'admin123',
    'letmein', 'welcome1', 'welcome123', 'abc12345', 'football',
    'sunshine', 'princess', 'baseball', 'trustno1', 'starwars',
    'india123', 'student123',
]);

// 1. Request OTP
export const requestOtp = async (req, res) => {
    try {
        const { email } = req.body;

        if (!email) {
            return res.status(400).json({ error: 'Email is required' });
        }

        // Extract the domain (e.g., from 'student@iiitk.ac.in' -> 'iiitk.ac.in')
        const domain = email.split('@')[1];
        if (!domain) {
            return res.status(400).json({ error: 'Invalid email format' });
        }

        // Check if the domain exists in our universities table
        const { data: university, error: uniError } = await supabase
            .from('universities')
            .select('id, name')
            .eq('domain', domain)
            .single();

        if (uniError || !university) {
            return res.status(403).json({ 
                error: 'Unauthorized Domain. Yahora is not yet available at your university.' 
            });
        }

        // If domain is valid, tell Supabase to send the OTP
        const { data, error } = await supabase.auth.signInWithOtp({
            email: email,
            options: {
                shouldCreateUser: true, // Creates the user in auth.users if they are new
            }
        });

        if (error) throw error;

        res.status(200).json({ 
            message: 'OTP sent successfully!', 
            university: university.name 
        });

    } catch (error) {
        console.error('OTP Request Error:', error);
        res.status(500).json({ error: 'Internal server error while sending OTP.' });
    }
};

// 2. Verify OTP
export const verifyOtp = async (req, res) => {
    try {
        const { email, otp } = req.body;

        if (!email || !otp) {
            return res.status(400).json({ error: 'Email and OTP are required' });
        }

        // 1. Verify token with Supabase.
        // On a throwaway client: verifyOtp() returns a session, and supabase-js
        // would adopt it and send that student's `authenticated` JWT for every
        // later query on the same client. See config/supabase.js.
        const { data, error } = await createSessionClient().auth.verifyOtp({
            email,
            token: otp,
            type: 'email'
        });

        if (error) throw error;

        // 2. Extract domain and get university_id
        const domain = email.split('@')[1];
        const { data: university, error: uniError } = await supabase
            .from('universities')
            .select('id')
            .eq('domain', domain)
            .single();

        if (uniError || !university) throw new Error('University not found for this domain.');

        // 3. Check if user already exists in our public 'users' table
        let { data: publicUser, error: userFetchError } = await supabase
            .from('users')
            .select('*')
            .eq('id', data.user.id)
            .single();

        // 4. If they don't exist, this is their first time logging in. Create the base profile.
        //
        // UPSERT, not insert (CC-4 Part E). migration 005's on_auth_user_created
        // trigger normally creates this row inside the same transaction as the
        // auth insert, so this branch is now a FALLBACK for the day the trigger
        // is missing — dropped by a Supabase upgrade, or a database restored
        // from before 005. ignoreDuplicates keeps the trigger's row untouched
        // when both run: the trigger's version is authoritative and identical.
        if (!publicUser) {
            const { data: newUser, error: insertError } = await supabase
                .from('users')
                .upsert([{ 
                    id: data.user.id, 
                    university_id: university.id,
                    is_profile_complete: false // Explicitly set to false
                }], { onConflict: 'id', ignoreDuplicates: true })
                .select()
                .maybeSingle();

            if (insertError) throw insertError;

            // ignoreDuplicates makes this DO NOTHING, which returns zero rows
            // when the trigger won the race. Re-read rather than .single() on
            // nothing, which would surface as a 500 on a successful signup.
            if (newUser) {
                publicUser = newUser;
            } else {
                const { data: existing, error: refetchError } = await supabase
                    .from('users')
                    .select('*')
                    .eq('id', data.user.id)
                    .single();
                if (refetchError) throw refetchError;
                publicUser = existing;
            }
        }

        // 5. Send response to frontend
        // Neeraj will check `userProfile.is_profile_complete`. 
        // If false, he routes them to /onboarding. If true, to /home.
        res.status(200).json({
            message: 'Authentication successful',
            session: data.session, 
            userAuth: data.user,
            userProfile: publicUser 
        });

    } catch (error) {
        console.error('OTP Verify Error:', error);
        res.status(500).json({ error: 'Internal server error while verifying OTP.' });
    }
};

// Onboarding Controller
// Inside backend/src/modules/auth/auth.controller.js

/**
 * Why the handle is unavailable — a LABEL, not a second opinion.
 *
 * is_username_available() has already decided. It returns one boolean for four
 * different reasons, and the client needs to know which. This asks the same
 * three tables the function asks, purely to name the reason it already gave.
 *
 * What this must never become: a JS reimplementation of the rules. There is no
 * regex here and no copy of the reserved list — INVALID_FORMAT is what is left
 * when none of the three lookups hit, by elimination. If this file ever grows
 * its own opinion about what a valid handle looks like, it will drift from
 * `users_username_valid` and we get a class of bug nobody can reproduce: the
 * check says free, the insert says no.
 *
 * Failure path only, so three indexed lookups in parallel is the right cost.
 * All three tables are RLS-on / zero-grant; this works because the backend
 * client is service_role, which bypasses RLS.
 */
async function classifyUnavailableUsername(username, userId) {
    const [reserved, taken, released] = await Promise.all([
        supabase
            .from('reserved_usernames')
            .select('username')
            .eq('username', username)
            .maybeSingle(),
        supabase
            .from('users')
            .select('id')
            .eq('username', username)
            .neq('id', userId)
            .maybeSingle(),
        supabase
            .from('username_history')
            .select('username')
            .eq('username', username)
            .gt('reserved_until', new Date().toISOString())
            .neq('user_id', userId)
            .limit(1),
    ]);

    if (reserved.data) return 'USERNAME_RESERVED';
    if (taken.data) return 'USERNAME_TAKEN';

    // Inside someone else's 30-day cooling-off window. Indistinguishable from
    // "taken" to the student, and saying "released 3 days ago by <someone>"
    // would leak who used to hold it.
    if (released.data?.length) return 'USERNAME_TAKEN';

    return 'INVALID_FORMAT';
}

// 3. Complete Onboarding
//
// 🔒 SECURITY (runbook Block D / CC-4 Part A). This used to take `userId` from
// the request body on a route with no auth middleware, so anyone who knew a
// UUID could overwrite that student's profile. Now that the same endpoint sets
// the account password, that same hole would have been full account takeover.
//
// The id comes from `req.user.id` — the Bearer token verified by requireAuth —
// and from nowhere else. `userId` is deliberately NOT destructured below: a
// caller may still send it, and it is ignored in silence. Erroring on it would
// only tell an attacker the parameter used to work.
// ─────────────────────────────────────────────────────────────────────────────
// Replacing the session that a password change destroys
//
// `supabase.auth.admin.updateUserById(userId, { password })` makes GoTrue
// delete EVERY session belonging to that user — auth.sessions and
// auth.refresh_tokens both drop to zero — including the one the caller is
// holding at that exact moment. Verified 2026-08-25 by
// backend/scripts/diagnose-token.mjs: sessions 2 → 0, refresh_tokens 2 → 0,
// and GoTrue answers 403 session_not_found for a token with 59 minutes left.
//
// **That revocation is the property we want** and it is deliberately NOT
// changed here. A password change SHOULD log out every other device. What it
// must not do is log out the person performing it. So the caller — and only
// the caller — is handed a replacement, minted from the password they just set.
//
// On a THROWAWAY client, never the shared `supabase`. signInWithPassword
// stores the session it returns on the client instance, which would demote the
// one shared service-role client to that student's `authenticated` JWT for
// every later query the process makes, until it restarts. See
// config/supabase.js:32 and the three existing call sites.
//
// Returns a session, or null. **This never throws and never fails a request.**
// By the time it runs the password change has already committed, and GoTrue
// gives us nothing to roll back with. A caller who gets no `session` is exactly
// where they were before this fix — logged out, but with a password that
// works. A 500 after a successful password change would be strictly worse: the
// student would not know which password their account now has.
async function mintReplacementSession(email, password, context) {
    if (!email) {
        // Every account is created from a university address, so this is a
        // corrupt-state guard rather than a real branch.
        console.error(`[${context}] auth user has no email — cannot mint a replacement session`);
        return null;
    }

    try {
        const { data, error } = await createSessionClient().auth.signInWithPassword({
            email,
            password,
        });

        if (error || !data?.session) {
            // GoTrue's own status, code and message. Never the password.
            console.error(`[${context}] re-signin failed — caller keeps a revoked token`, {
                email,
                status:  error?.status ?? null,
                code:    error?.code ?? null,
                message: error?.message ?? 'signInWithPassword returned no session',
            });
            return null;
        }

        return data.session;
    } catch (err) {
        console.error(`[${context}] re-signin threw — caller keeps a revoked token`, {
            email,
            message: err?.message ?? String(err),
        });
        return null;
    }
}

export const completeOnboarding = async (req, res) => {
    try {
        // The ONLY source of identity in this handler.
        const userId = req.user.id;

        const {
            full_name,
            avatar_url,
            qualification,
            course_id,
            year_of_study,
            specialization_id,
            bio,
            username: rawUsername,
            password,
        } = req.body;

        // ── 1. Validate everything BEFORE touching the password or the row ──
        if (!full_name || !qualification || !course_id || !year_of_study || !specialization_id) {
            return sendError(res, 400, 'MISSING_FIELDS', {
                message: 'Name, Qualification, Course, Year, and Specialization are mandatory.',
            });
        }

        if (bio && bio.length > 250) {
            return sendError(res, 400, 'CONTENT_TOO_LONG', {
                max: 250,
                message: 'Bio must be 250 characters or less.',
            });
        }

        // Fold first, exactly as is_username_available() does internally, so a
        // caps-lock student asking about RAHUL is answered about rahul.
        const username = typeof rawUsername === 'string' ? rawUsername.trim().toLowerCase() : '';

        if (!username) {
            return sendError(res, 400, 'INVALID_FORMAT', {
                message: 'A username is required to complete onboarding.',
            });
        }

        // Password. Username and password are both compulsory at onboarding
        // (runbook §0.6) — there is no partial state to design around.
        if (typeof password !== 'string' || password.length < MIN_PASSWORD_LENGTH) {
            return sendError(res, 400, 'WEAK_PASSWORD', {
                message: `Password must be at least ${MIN_PASSWORD_LENGTH} characters.`,
            });
        }

        if (COMMON_PASSWORDS.has(password.toLowerCase())) {
            return sendError(res, 400, 'COMMON_PASSWORD', {
                message: 'That password is too common. Please choose another.',
            });
        }

        if (password.toLowerCase() === username) {
            return sendError(res, 400, 'WEAK_PASSWORD', {
                message: 'Your password cannot be the same as your username.',
            });
        }

        // The database owns every username rule: charset, length, the reserved
        // list, and the 30-day cooling-off window. Do not re-derive any of them
        // here — see classifyUnavailableUsername above.
        const { data: isAvailable, error: rpcError } = await supabase.rpc('is_username_available', {
            p_username: username,
            p_user_id:  userId,
        });

        if (rpcError) return mapDbError(res, rpcError);

        if (isAvailable !== true) {
            const code = await classifyUnavailableUsername(username, userId);
            return sendError(res, 400, code);
        }

        // ── 2. Set the password. This must come BEFORE the profile update. ──
        //
        // Order is not cosmetic. If is_profile_complete went true first and this
        // call then failed, the student would be stranded forever: a complete
        // profile the app never sends back to onboarding, and no password, with
        // nothing left to prompt them. The reverse failure is harmless — they
        // retry onboarding and the password is simply set again.
        const { error: passwordError } = await supabase.auth.admin.updateUserById(userId, {
            password,
        });

        if (passwordError) {
            // Log the status and GoTrue's own message. Never the password.
            console.error('[onboarding] password update failed', {
                userId,
                status:  passwordError.status,
                message: passwordError.message,
            });

            // GoTrue rejects on its own policy too (its minimum length, or a
            // password it has seen in a breach corpus). That is the student's
            // input, not our bug — 400, not 500.
            const isValidation = passwordError.status === 400 || passwordError.status === 422;
            return isValidation
                ? sendError(res, 400, 'WEAK_PASSWORD', {
                      message: 'That password was rejected. Please choose another.',
                  })
                : sendError(res, 500, 'INTERNAL_ERROR');
        }

        // ── 3. Only now: the profile row, complete, with the handle. ──
        const { data: updatedUser, error: updateError } = await supabase
            .from('users')
            .update({
                full_name,
                username,
                avatar_url:          avatar_url || null,
                qualification,       // Frontend string (e.g., 'Graduation')
                course_id,           // UUID from the database
                year_of_study,       // Frontend string (e.g., '3rd year')
                specialization_id,   // UUID from the database
                bio:                 bio || null,
                is_profile_complete: true,
                has_password:        true,
            })
            .eq('id', userId)
            .select()
            .maybeSingle();

        if (updateError) throw updateError;

        // maybeSingle, not single: a missing profile row is a 404, not a 500.
        // migration 005's on_auth_user_created makes this near-impossible.
        if (!updatedUser) {
            return sendError(res, 404, 'NOT_FOUND', {
                message: 'No profile exists for this account.',
            });
        }

        // ── 4. Replace the session step 2 just destroyed. ───────────────────
        //
        // Step 2 revoked every session for this user, the token that
        // authenticated THIS request included, so without a replacement the
        // student is logged out at the instant they finish signing up. CC-4
        // recorded this as an open question; this is the answer.
        //
        // Additive: `message` and `userProfile` are unchanged.
        const session = await mintReplacementSession(req.user.email, password, 'onboarding');

        const body = {
            message: 'Profile completed successfully!',
            userProfile: updatedUser,
        };

        // Omitted entirely when the re-signin failed, never sent as null. A
        // client seeing no `session` must re-authenticate — it is not an error,
        // and the profile above is already saved.
        if (session) body.session = session;

        return res.status(200).json(body);

    } catch (error) {
        // 🎯 THE CATCH THIS ENDPOINT EXISTS FOR.
        //
        // is_username_available() said yes a few milliseconds ago. That is not
        // a reservation — two students can both be told yes and both submit.
        // The unique index users_username_key is the only thing that can
        // arbitrate, and it says so with 23505. Letting that reach the generic
        // handler would give the loser a 500 on a perfectly ordinary race.
        //
        // mapDbError maps 23505 to the generic DUPLICATE; on this endpoint the
        // only unique column in play is the handle, so it is named here first.
        // respond.js is frozen shared infra — this is the specialisation point.
        if (error?.code === '23505') {
            return sendError(res, 400, 'USERNAME_TAKEN');
        }

        // Everything else, including trg_username_not_reserved raising
        // USERNAME_RESERVED, which mapDbError already recognises by message.
        return mapDbError(res, error);
    }
};

// 4. Demo Login (Interactive Sandbox)
export const demoLogin = async (req, res) => {
    try {
        // 1. Generate unique temporary credentials
        const timestamp = Date.now();
        const randomStr = Math.random().toString(36).substring(2, 8);
        const demoEmail = `guest_${timestamp}_${randomStr}@demo.yahora.com`;
        const demoPassword = `Demo!${timestamp}${randomStr}`; 

        // 2. Fetch the Demo University ID
        const { data: university, error: uniError } = await supabase
            .from('universities')
            .select('id, name')
            .eq('domain', 'demo.yahora.com')
            .single();

        if (uniError || !university) {
            return res.status(500).json({ 
                error: 'Demo university not found. Please run the seed script first.' 
            });
        }

        // 3. Create the user using the Admin API (auto-confirms the email)
        const { data: authData, error: createError } = await supabase.auth.admin.createUser({
            email: demoEmail,
            password: demoPassword,
            email_confirm: true
        });

        if (createError) throw createError;

        // 4. Sign in immediately to generate a valid session token for the frontend.
        // On a throwaway client for the same reason as verifyOtp above — otherwise
        // step 5's insert runs as the demo user and hits 42501. See config/supabase.js.
        const { data: signInData, error: signInError } = await createSessionClient().auth.signInWithPassword({
            email: demoEmail,
            password: demoPassword
        });

        if (signInError) throw signInError;

        // 5. Create their public profile
        // Notice we set is_profile_complete: false so they STILL see the onboarding screen!
        //
        // UPSERT, not insert (CC-4 Part E). This one was actively broken: every
        // demo login mints a brand-new auth user, so on_auth_user_created has
        // ALWAYS created this row by the time we get here, and a plain insert
        // hit 23505 on the primary key and returned 500 for every call.
        const { data: inserted, error: insertError } = await supabase
            .from('users')
            .upsert([{
                id: signInData.user.id,
                university_id: university.id,
                is_profile_complete: false 
            }], { onConflict: 'id', ignoreDuplicates: true })
            .select()
            .maybeSingle();

        if (insertError) throw insertError;

        // DO NOTHING returns zero rows, which is the normal path now that the
        // trigger exists. Read back the row it created.
        let newUser = inserted;
        if (!newUser) {
            const { data: existing, error: refetchError } = await supabase
                .from('users')
                .select('*')
                .eq('id', signInData.user.id)
                .single();
            if (refetchError) throw refetchError;
            newUser = existing;
        }

        // 6. Return the exact same payload structure as verifyOtp
        res.status(200).json({
            message: 'Demo login successful',
            session: signInData.session,
            userAuth: signInData.user,
            userProfile: newUser
        });

    } catch (error) {
        console.error('Demo Login Error:', error);
        res.status(500).json({ error: 'Internal server error during demo login.' });
    }
};
// ═══════════════════════════════════════════════════════════════════════════
// PASSWORD LOGIN — runbook Block E / CC-5
//
// Three endpoints: login-password (public), set-password (auth'd),
// password-status (auth'd).
//
// The single most important property of this section: **every failure of
// login-password is byte-for-byte identical.** Wrong password, unknown
// username, unknown email, and an account that never finished onboarding all
// produce the same status, the same code and the same sentence. If any one of
// them differed — even in wording — an attacker could enumerate which
// identifiers are real, then concentrate guessing on those. On a campus app
// that is worse than wasted effort: it also answers "is this specific
// classmate on Yahora?", which is a harassment precursor. See runbook §0.6.
//
// Nothing here logs, stores or returns a password. The only credential-shaped
// value that ever leaves the process is the boolean `has_password`.
// ═══════════════════════════════════════════════════════════════════════════

// Lockout: 10 failures for one identifier inside 15 minutes.
const LOGIN_WINDOW_SECONDS  = 15 * 60;
const LOGIN_MAX_FAILURES    = 10;

// Longest address RFC 5321 permits. Anything longer is not an identifier
// anyone owns, so it is rejected before it can be written to the ledger —
// otherwise auth_attempts is a free write primitive for arbitrary-size rows.
const MAX_IDENTIFIER_LENGTH = 320;

// ⚠️ ONE STRING. Do not add a second, do not branch it, do not "improve" one
// caller's copy. Every login failure returns exactly this.
const INVALID_CREDENTIALS_MESSAGE = 'Incorrect username or password. Please try again.';

const sendInvalidCredentials = (res) =>
    sendError(res, 400, 'INVALID_CREDENTIALS', { message: INVALID_CREDENTIALS_MESSAGE });

/**
 * Append one row to the lockout ledger.
 *
 * `identifier` is what the student typed, folded to lowercase — the lock is on
 * the identifier, never on the IP. Campus Wi-Fi NATs an entire hostel behind
 * one address, so an IP lock would take out hundreds of students because one
 * person fat-fingered their password. ip_address is recorded for later
 * analysis and is NEVER read by the limiter.
 *
 * A failure to write is logged and swallowed. The alternative — 500 on a
 * successful login because the audit insert failed — is worse than a missing
 * ledger row.
 */
async function recordAuthAttempt(identifier, ip, succeeded) {
    const { error } = await supabase
        .from('auth_attempts')
        .insert([{ identifier, ip_address: ip || null, succeeded }]);

    if (error) {
        console.error('[login] could not record auth attempt', {
            identifier, succeeded, message: error.message,
        });
    }
}

// 5. Login with username-or-email + password
//
// Order matters and is not negotiable: rate limit FIRST, before a single
// credential is touched. A limiter that runs after the password check gives an
// attacker one free verification per request no matter how locked the account
// is.
export const loginWithPassword = async (req, res) => {
    try {
        const rawIdentifier = req.body?.identifier;
        const password      = req.body?.password;

        // Fold once, here. Everything downstream — the ledger key, the RPC, the
        // username lookup — uses this exact value, so `Rahul` and `rahul ` count
        // against the same lock instead of getting ten fresh attempts each.
        const identifier = typeof rawIdentifier === 'string'
            ? rawIdentifier.trim().toLowerCase()
            : '';

        // Nothing to attribute an attempt to, and nothing that could be a real
        // account. No ledger row — a malformed body is not a probe.
        if (!identifier || identifier.length > MAX_IDENTIFIER_LENGTH) {
            return sendInvalidCredentials(res);
        }

        // ── 1. RATE LIMIT, before touching any credential ──────────────────
        //
        // One query answers both questions. Ordered newest-first and capped at
        // the threshold, so the last row is the 10th-newest failure — the one
        // whose expiry drops the count back to 9 and ends the lock. That gives
        // an honest retry_after_seconds instead of a flat 900 that tells a
        // student to wait 15 minutes when they have 40 seconds left.
        //
        // Reads auth_attempts_failed_idx (identifier, created_at desc) WHERE
        // succeeded = false — successes are not in that index at all.
        const windowStart = new Date(Date.now() - LOGIN_WINDOW_SECONDS * 1000).toISOString();

        const { data: recentFailures, error: ledgerError } = await supabase
            .from('auth_attempts')
            .select('created_at')
            .eq('identifier', identifier)
            .eq('succeeded', false)
            .gte('created_at', windowStart)
            .order('created_at', { ascending: false })
            .limit(LOGIN_MAX_FAILURES);

        // Fail CLOSED. If the ledger is unreadable we cannot count attempts,
        // and an unlimited-guessing window is a worse outcome than a login
        // outage — which this already is, since the same database holds the
        // profile row this endpoint has to return.
        if (ledgerError) return mapDbError(res, ledgerError);

        const failures = recentFailures || [];

        if (failures.length >= LOGIN_MAX_FAILURES) {
            const oldestCounted = failures[failures.length - 1];
            const unlocksAt = new Date(oldestCounted.created_at).getTime()
                            + LOGIN_WINDOW_SECONDS * 1000;
            const retryAfterSeconds = Math.max(
                1,
                Math.min(LOGIN_WINDOW_SECONDS, Math.ceil((unlocksAt - Date.now()) / 1000)),
            );

            // The lock is on the identifier, not on being wrong: a correct
            // password while locked is still a 429. That is what makes it a
            // lockout rather than a speed bump.
            res.set('Retry-After', String(retryAfterSeconds));
            return sendError(res, 429, 'TOO_MANY_ATTEMPTS', {
                retry_after_seconds: retryAfterSeconds,
                message: 'Too many failed attempts. Please try again later.',
            });
        }

        // A missing password is still a spent attempt. It cannot probe for
        // existence — the answer below is identical either way — but it must
        // not be free, or the limiter is trivially skipped.
        if (typeof password !== 'string' || password.length === 0) {
            await recordAuthAttempt(identifier, req.ip, false);
            return sendInvalidCredentials(res);
        }

        // ── 2. Resolve the identifier to an identity ──────────────────────
        //
        // One field, both forms — Instagram does this and students expect it.
        // Supabase can only sign in by email, so a handle has to be mapped
        // first.
        //
        // get_login_identity() (migration 007) answers for BOTH forms in one
        // round trip: id, email, has_password. It replaces the old pair of
        // lookups — get_login_email() plus a `users` select — which between
        // them could only ever describe a HANDLE. That asymmetry was the bug:
        // an email login could not reach the has_password check at all, and
        // the one student the check exists for (OTP verified, onboarding
        // abandoned) has username NULL, so email is the only identifier they
        // have. The branch below was unreachable for exactly the population it
        // was written for. See API.md and the migration header.
        //
        // SECURITY DEFINER and revoked from anon, authenticated and PUBLIC —
        // it maps a public handle to a private address and discloses whether
        // an account exists at all, so only the service-role client may call
        // it.
        const { data: identityRows, error: identityError } = await supabase.rpc(
            'get_login_identity',
            { p_identifier: identifier },
        );

        if (identityError) return mapDbError(res, identityError);

        // `returns table` comes back as an array over PostgREST, capped at one
        // row by the function's own LIMIT.
        const identity = Array.isArray(identityRows) ? identityRows[0] : identityRows;

        // ── 3. No such account → generic failure ──────────────────────────
        //
        // "User not found" would be the enumeration oracle this whole endpoint
        // is shaped to avoid. Log the attempt first: if a failed lookup were
        // free, someone could probe thousands of handles a minute at no cost.
        if (!identity?.email) {
            await recordAuthAttempt(identifier, req.ip, false);
            return sendInvalidCredentials(res);
        }

        const email = identity.email;

        // ── 4. Account with no password → SAME generic failure ────────────
        //
        // Reachable one way only: OTP verified, then onboarding abandoned, so
        // the row exists with has_password = false. Onboarding abandonment is
        // normal, so this must not 500 — and it must not look different from a
        // wrong password either. The real reason goes to the SERVER CONSOLE
        // and nowhere near the response. PASSWORD_NOT_SET is deliberately not
        // an API code; see runbook §0.6.
        //
        // Now fires for an email identifier too, which is the only kind this
        // student can actually type.
        if (identity.has_password !== true) {
            console.warn(`[login] has_password=false for ${identity.id} — onboarding never finished`);
            await recordAuthAttempt(identifier, req.ip, false);
            return sendInvalidCredentials(res);
        }

        // ── 5. Sign in — on a THROWAWAY client ────────────────────────────
        //
        // createSessionClient(), never the shared `supabase`. supabase-js
        // stores the session this call returns on the client instance, so
        // signing in on the shared service-role client demotes it to that
        // student's `authenticated` JWT for every later query the process
        // makes, until it restarts. That outage already happened once — see
        // docs/CHANGELOG.md 2026-08-12 and config/supabase.js.
        const { data: signInData, error: signInError } =
            await createSessionClient().auth.signInWithPassword({ email, password });

        // ── 6. Wrong password → byte-identical to step 3 ──────────────────
        //
        // GoTrue itself does not distinguish "no such user" from "wrong
        // password" from "user has no password" — all three are
        // invalid_credentials — and neither do we.
        if (signInError || !signInData?.session || !signInData?.user) {
            await recordAuthAttempt(identifier, req.ip, false);
            return sendInvalidCredentials(res);
        }

        // ── 7. Success ────────────────────────────────────────────────────
        await recordAuthAttempt(identifier, req.ip, true);

        // Clear the lock. Scoped to succeeded = false so the success row just
        // written survives as an audit trail. A student who fails nine times
        // and then remembers their password starts the next session clean.
        const { error: clearError } = await supabase
            .from('auth_attempts')
            .delete()
            .eq('identifier', identifier)
            .eq('succeeded', false);

        if (clearError) {
            console.error('[login] could not clear failed attempts', {
                identifier, message: clearError.message,
            });
        }

        const { data: userProfile, error: profileError } = await supabase
            .from('users')
            .select('*')
            .eq('id', signInData.user.id)
            .maybeSingle();

        if (profileError) return mapDbError(res, profileError);

        // Near-impossible since on_auth_user_created creates the row inside the
        // auth insert's own transaction. A 404 rather than a 500 so that if it
        // ever does happen it reads as "no profile", not "server broken".
        if (!userProfile) {
            return sendError(res, 404, 'NOT_FOUND', {
                message: 'No profile exists for this account.',
            });
        }

        // EXACTLY the verify-otp shape, same message string included. Both
        // clients store a session the same way for OTP, demo and password
        // login; none of them needs a second code path.
        return res.status(200).json({
            message:     'Authentication successful',
            session:     signInData.session,
            userAuth:    signInData.user,
            userProfile,
        });

    } catch (error) {
        console.error('[login] unexpected error', error);
        return mapDbError(res, error);
    }
};

// 6. Set or change the account password (settings screen)
//
// First set: no proof beyond the Bearer token. A later change: current_password
// required. The asymmetry is deliberate — the first set happens during
// onboarding seconds after the student proved they own the university inbox,
// while a change could be someone at a phone left unlocked on a library desk.
export const setPassword = async (req, res) => {
    try {
        const userId = req.user.id;
        const { password, current_password: currentPassword } = req.body || {};

        // ── Password policy — identical to CC-4's, same constants ─────────
        if (typeof password !== 'string' || password.length < MIN_PASSWORD_LENGTH) {
            return sendError(res, 400, 'WEAK_PASSWORD', {
                message: `Password must be at least ${MIN_PASSWORD_LENGTH} characters.`,
            });
        }

        if (COMMON_PASSWORDS.has(password.toLowerCase())) {
            return sendError(res, 400, 'COMMON_PASSWORD', {
                message: 'That password is too common. Please choose another.',
            });
        }

        const { data: profile, error: profileError } = await supabase
            .from('users')
            .select('id, username, has_password')
            .eq('id', userId)
            .maybeSingle();

        if (profileError) return mapDbError(res, profileError);

        if (!profile) {
            return sendError(res, 404, 'NOT_FOUND', {
                message: 'No profile exists for this account.',
            });
        }

        if (profile.username && password.toLowerCase() === profile.username) {
            return sendError(res, 400, 'WEAK_PASSWORD', {
                message: 'Your password cannot be the same as your username.',
            });
        }

        // ── Changing an existing password requires proving you know it ────
        if (profile.has_password === true) {
            if (typeof currentPassword !== 'string' || currentPassword.length === 0) {
                return sendError(res, 400, 'MISSING_FIELDS', {
                    message: 'Your current password is required to change it.',
                });
            }

            // No email means no way to verify, and no way to sign in either.
            // Every account here is created from a university address, so this
            // is a corrupt-state guard, not a real branch.
            if (!req.user.email) {
                console.error('[set-password] auth user has no email', { userId });
                return sendError(res, 500, 'INTERNAL_ERROR');
            }

            // Throwaway client again — same demotion trap as login above.
            const { data: verified, error: verifyError } =
                await createSessionClient().auth.signInWithPassword({
                    email:    req.user.email,
                    password: currentPassword,
                });

            if (verifyError || !verified?.user) {
                // Distinct from INVALID_CREDENTIALS on purpose: the caller is
                // already authenticated, so there is no account to enumerate
                // and no reason to be vague about which field was wrong.
                return sendError(res, 401, 'INVALID_CURRENT_PASSWORD', {
                    message: 'Your current password is incorrect.',
                });
            }
        }

        // ── Set it, then flip the cache ───────────────────────────────────
        const { error: updateError } = await supabase.auth.admin.updateUserById(userId, {
            password,
        });

        if (updateError) {
            // GoTrue's own status and message. Never the password.
            console.error('[set-password] password update failed', {
                userId,
                status:  updateError.status,
                message: updateError.message,
            });

            // GoTrue applies its own policy on top of ours (its minimum length,
            // or a password it has seen in a breach corpus). That is the
            // student's input, not our bug — 400, not 500.
            const isValidation = updateError.status === 400 || updateError.status === 422;
            return isValidation
                ? sendError(res, 400, 'WEAK_PASSWORD', {
                      message: 'That password was rejected. Please choose another.',
                  })
                : sendError(res, 500, 'INTERNAL_ERROR');
        }

        // has_password is a CACHE of auth.users.encrypted_password (migration
        // 005 §2). It is written only after GoTrue confirms the real change, so
        // it can never claim a password that does not exist.
        const { error: flagError } = await supabase
            .from('users')
            .update({ has_password: true })
            .eq('id', userId);

        if (flagError) return mapDbError(res, flagError);

        // ── Replace the session the update just destroyed ─────────────────
        //
        // Same revocation as onboarding: every other device is now logged out,
        // which is the point. The student who typed the new password is not.
        const session = await mintReplacementSession(req.user.email, password, 'set-password');

        const body = { message: 'Password set', has_password: true };
        if (session) body.session = session;

        return res.status(200).json(body);

    } catch (error) {
        console.error('[set-password] unexpected error', error);
        return mapDbError(res, error);
    }
};

// 7. Does this account have a password?
//
// The only credential-adjacent fact this API ever discloses, and it is scoped
// to the caller's own row — req.user.id, never a parameter.
export const getPasswordStatus = async (req, res) => {
    try {
        const { data: profile, error } = await supabase
            .from('users')
            .select('has_password')
            .eq('id', req.user.id)
            .maybeSingle();

        if (error) return mapDbError(res, error);

        if (!profile) {
            return sendError(res, 404, 'NOT_FOUND', {
                message: 'No profile exists for this account.',
            });
        }

        return res.status(200).json({ has_password: profile.has_password === true });

    } catch (error) {
        console.error('[password-status] unexpected error', error);
        return mapDbError(res, error);
    }
};
